/* 教学内容与案例。所有对话示例均为预先编写的教学演示。 */
const LESSONS = [
 {title:'先认识 AI，再选工具',desc:'产品和模型有什么区别？先按你要做的事来选。',icon:'✦',color:'',time:8,tag:'入门认知',goal:'能够为一件小事，选到合适的工具和模式。',sections:[
  ['先把 AI 当成一位需要交代背景的助手','<p>大模型能根据你给的文字、图片和材料，生成解释、草稿或方案。接上工具的 AI 产品，还可能查资料、处理文件、制作网页。它可能理解错，也可能把不确定的事说得很肯定，所以你仍然负责判断结果。</p><div class="comparison"><div><strong>产品 = 你使用的工作台</strong><p>例如 Codex、WorkBuddy、豆包。界面、文件能力和可用工具由产品决定。</p></div><div><strong>模型 = 工作台里的思考能力</strong><p>同一产品可能有多种模型或模式。换模型不等于自动获得联网、文件读写等权限。</p></div></div>'],
  ['三个产品，怎样开始？','<ul><li><b>Codex：</b>可以从制作、修改网页和处理项目文件开始练习。新建练习文件夹，再给出要交付的结果。官方文档入口可能随版本调整。</li><li><b>WorkBuddy：</b>可用自然语言描述办公任务，在授权范围内处理本地文件。先拿资料副本练习，再检查生成的结果。</li><li><b>豆包的办公用途：</b>可以从解释材料、写草稿和截图问答入手。本文用“豆包办公”指豆包用于办公的场景，不假设每个版本都有相同的文件导出功能。</li></ul><p>从本课底部的官方资料入口安装或登录。只把练习用的文件交给它；不要一开始就授权整个磁盘。</p>'],
  ['选模型，看任务需要','<p>先用产品默认模式完成小样。改写短通知优先看速度；多条件方案、复杂推理可试更强的思考模式；制作网页还要看文件与执行能力。看图片需要图像输入；查最新信息需要搜索工具，而不只是更强的模型。</p><div class="callout">用同一份小任务比较：有没有遵守要求？事实是否正确？需要改几次？花多少时间或额度？不必为了模型名先购买订阅。</div><p>具体可用模型、价格、地区与套餐会变化，请以你的界面和官方说明为准。</p>']
 ],practice:'model',prompt:'我刚开始使用 AI。请帮我完成一个小任务：把下面的活动信息整理成一条 150 字以内的通知。先检查是否缺少时间、地点、对象，再写草稿；不要编造信息。活动信息：[粘贴你的材料]。',quiz:{q:'我要查询今天的天气，该优先确认什么？',options:['模型的名字是不是最新','是否能获取实时天气或联网资料','回答的字数是否足够多'],answer:1,explain:'实时信息需要可靠的最新来源。模型再强，也不能靠旧知识保证今天的天气。'}},
 {title:'怎么提问？说不清时怎么办？',desc:'先说你想做什么，缺的细节可以让 AI 问你。',icon:'“ ”',color:'green',time:9,tag:'提问方法',goal:'写出一条可执行的需求，并学会确认 AI 是否理解。',sections:[
  ['一次没说全也没关系，先说这几件事','<p>先说你要什么结果，再补会影响结果的信息。目标是“做一份家长会材料”；对象是“三年级学生家长”；材料是“班级匿名情况”；要求是“温和、20 分钟”；成品是“8 页 PPT”。简单问题不必套完整模板。</p><div class="comparison"><div><strong>信息太少</strong><p>帮我做个好看的 PPT。</p></div><div><strong>更容易得到有用的结果</strong><p>给三年级家长做 8 页家长会 PPT，讲阅读习惯，演讲 20 分钟。先给每页标题和重点，确认后制作。</p></div></div>'],
  ['说不清，就让 AI 来采访你','<p>不需要先学会专业词。描述你不满意的地方，给一个喜欢的例子，或者请它提供两三种选择。一次只回答一个问题也可以。</p><div class="callout">“我还说不清需求。请一次问我一个问题，给 2–3 个容易理解的选项。先问用途和使用对象，等我回答再继续。收集完后，用五句话复述，等我确认。”</div>'],
  ['确认理解，不只是回复“好的”','<ol class="number-steps"><li><b>让它复述</b>说出目标、已知事实、假设和还缺的信息。</li><li><b>看一个小样</b>先看一页 PPT、一段文档或一个网页模块，再做整份。</li><li><b>说具体一点，告诉它哪里要改</b>“第 2 页字太密，保留 3 个重点，每点不超过 20 字”，比“再高级一点”更有效。</li></ol><p>一次集中改一类问题。保留满意的部分，并明确告诉它哪些地方不要改。</p>']
 ],practice:'prompt',prompt:'我想做[事情]，但还没想清楚。请先别制作，像耐心的访谈老师一样，一次问我一个问题，并给 2–3 个选项。了解用途、对象、材料、格式和限制后，复述你的理解，列出假设，等我确认。',quiz:{q:'AI 做出的通知太生硬，怎样反馈更有效？',options:['不行，重新做','再优化一下','保留时间地点，把开头改亲切；给两个版本，每版不超过 150 字'],answer:2,explain:'具体指出保留什么、修改什么、如何判断好坏，能减少反复。'}},
 {title:'请 AI 做一个可以点击的网页',desc:'亲手切换 HTML、CSS、JS，看到三者分别做什么。',icon:'〈〉',color:'purple',time:10,tag:'网页呈现',goal:'知道何时选网页，并能提出离线、可打包的网页需求。',sections:[
  ['同一份内容，可以变得更好用','<p>HTML 放标题、段落和按钮，CSS 决定字号、颜色和布局，JavaScript（简称 JS）让搜索、勾选、计算和切换真正工作。你不必先会写代码，可以让 AI 制作，再用真实操作来验收。</p><p>知识讲解可以有随堂题，旅行清单可以勾选，方案比较可以筛选。当前这个课堂就是一个 HTML + CSS + JS 的例子。</p>'],
  ['为什么有些内容适合做成网页？','<ul><li><b>打开门槛低：</b>纯静态、资源齐全的网页可以直接用浏览器打开。</li><li><b>内容与操作放在一起：</b>读完就能练习、搜索、复制，少来回翻材料。</li><li><b>修改直观：</b>告诉 AI 哪个区域、想怎样变化，改完刷新检查。</li><li><b>方便携带：</b>本地资源完整、没有服务端依赖的项目可以打包为 ZIP。</li></ul><div class="callout warn">并非所有网页都能双击或离线运行。外部图片、在线字体、接口、登录和多人数据同步可能需要网络或服务器；请在需求里明确“无外部依赖、支持 file:// 打开”。</div>'],
  ['什么时候换成 PPT、Word 或 Excel？','<p>会议演讲选 PPT；要签字、批注、按页打印选 Word 或 PDF；复杂公式和规范表格用 Excel。网页适合互动讲解和小工具，不替代所有格式。把网页截图贴进 PPT 也不等于可编辑的演示文稿。</p>']
 ],practice:'web',prompt:'请制作一个给家人使用的出行清单网站，使用 HTML、CSS 和原生 JavaScript。字号至少 18px，手机也能看，可勾选并显示完成数量。所有资源放在同一目录，禁止外部依赖和网络请求，完整解压后双击 index.html 即可运行。先给一个可操作的小样，再检查每个按钮。说明数据存在哪里，以及清理浏览器后会发生什么。',quiz:{q:'我想把网页 ZIP 发给爸妈，哪项验收最关键？',options:['压缩包文件名好看','在另一个目录解压，断网打开并操作所有功能','页面源码越长越好'],answer:1,explain:'必须验证资源路径和离线依赖。只在制作者电脑上能打开，还不代表交给别人也能用。'}},
 {title:'从一份大纲开始做 PPT',desc:'先看大纲，再试做两页，最后打开文件讲一遍。',icon:'▥',color:'orange',time:12,tag:'PPT 实战',goal:'完成一份有讲述顺序、能打开、能修改的演示文稿。',sections:[
  ['先决定听众离开时记住什么','<p>以家长会为例：目标是让家长掌握三个陪伴阅读的方法。听众是家长，时长 20 分钟，页数约 8 页。先准备可靠的班级材料和可公开的信息，学生姓名与个人成绩先去除。</p><div class="callout">不要只说“生成 8 页”。还要说：每页一个结论、用什么事实支撑、讲者要怎么过渡。</div>'],
  ['按四步做，返工更少','<ol class="number-steps"><li><b>先要逐页大纲</b>每页列标题、核心观点、所需素材和讲述时间。检查逻辑，不急着装饰。</li><li><b>先做两页小样</b>选封面和内容页，确认投影字号、对比度、图片风格。普通正文可先要求 24pt 以上，再按现场试读。</li><li><b>生成可编辑文件</b>明确要求 .pptx，文字可编辑，附讲者备注。如果产品只能给大纲，请直接说明，不要把文字草稿当作已生成文件。</li><li><b>打开并试讲</b>用 PowerPoint 或兼容软件放映，检查字体、图片、换行、页码和备注。实际计时，再删减。</li></ol>'],
  ['三类制作任务，先选一种练习','<ul><li><b>家长会：</b>8 页 / 20 分钟。结构：目标 → 现状 → 三种方法 → 一周行动 → 沟通方式。验收：无学生隐私、每页一个重点、行动清楚。</li><li><b>课堂微课：</b>6 页 / 10 分钟。结构：生活问题 → 概念 → 示范 → 练习 → 解释 → 小结。验收：难度符合年级、答案正确、字号清楚。</li><li><b>工作汇报：</b>7 页 / 10 分钟。结构：结论 → 目标 → 结果 → 证据 → 问题 → 下一步 → 需要支持。验收：每个数字有来源，不把计划当成果。</li></ul><p>案例演示可跟做家长会和工作汇报；备用模板中还有活动策划、读书分享和旅行说明。</p>'],
  ['看着漂亮，还要逐页检查','<p>避免编造引文、数据和图表；图片要有合法使用来源。不要依赖“AI 说已经检查”。亲自打开成品，看有没有文本溢出、遮挡、错别字，以及换电脑后字体替换。正式展示前保留 .pptx 和 PDF 备用。</p>']
 ],practice:'ppt',prompt:'请根据我提供的匿名材料，制作三年级家长会 PPT，主题是培养阅读习惯。听众为家长，20 分钟，8 页，每页一个重点。先给逐页大纲（标题、观点、素材、时间），缺少的事实用“待补充”标注。等我确认后先做封面和一张内容页小样。确认风格后再交付可编辑 .pptx，附讲者备注；文字不能全部做成图片。若当前工具不能生成文件，请明确说明，并给可粘贴到 PowerPoint 的逐页内容。',quiz:{q:'AI 给了“第 1 页、第 2 页”的文字，算 PPT 成品吗？',options:['算，有页码就是 PPT','还只是内容稿，需要生成文件并打开验收','只要说制作完成就算'],answer:1,explain:'文字大纲和可编辑 .pptx 是不同交付物。检查下载文件、可编辑性和真实放映效果。'}},
 {title:'请 AI 帮你做 Word 文档',desc:'通知、教案、纪要、报告，从材料到 Word 和 PDF。',icon:'▤',color:'green',time:11,tag:'文档实战',goal:'能提出文档结构和格式要求，并核对最终文件。',sections:[
  ['先区分草稿和正式文件','<p>聊天里的文字可以是草稿。需要打印、批注或提交时，明确要求可编辑 .docx；需要固定版式给人阅读时，再导出 PDF。不要仅把扩展名改成 .docx 或 .pdf，那不会完成格式转换。</p>'],
  ['一份活动通知，如何交给 AI？','<ol class="number-steps"><li><b>准备事实清单</b>活动名称、时间、地点、对象、准备事项、联系人。未知项写“待确认”，不让它补造。</li><li><b>定结构与语气</b>先给“标题—活动目的—安排—注意事项—落款”。告诉它用于家长群还是正式打印。</li><li><b>定成品格式</b>例如 A4、正文易读、控制一页、保留可编辑文字、输出 Word，同时导出 PDF。</li><li><b>检查文件</b>重新核对日期、星期、姓名、金额、表格与页边距。下载后在实际软件里打开，打印预览看是否多出空白页。</li></ol>'],
  ['不同文档，检查的重点也不同','<ul><li><b>教案：</b>列教学目标、重难点、课堂环节、时间、练习与答案。检查是否适合学生水平，总时长是否合理。</li><li><b>会议纪要：</b>区分讨论、已确认决定和待办。负责人或截止日不明确就标记“待确认”。</li><li><b>工作报告：</b>结论和证据对应，引用能追溯。不能把猜测写成已发生的事实。</li><li><b>申请书：</b>核对接收方的模板、签名和附件要求。以真实信息为准，不代造经历。</li></ul>'],
  ['让 AI 按材料写，而不是自由发挥','<p>告诉它“仅基于附件；缺失的信息单独列出；引用标明文件名和页码”。提交前抽查原文，尤其是数字、否定词和例外条件。扫描件识别可能出错，关键段落要比对原图。</p><div class="callout">修改也要具体：“保留第一段，把第二部分改成三列表格：事项、负责人、截止时间。未确认的格子写待确认。”</div>']
 ],practice:'doc',prompt:'请根据以下事实制作一份活动通知，面向学生家长，语气清楚亲切。仅使用材料，不编造时间地点。先列缺失信息，再给正文草稿。确认后生成可编辑 .docx，A4 一页，标题醒目、正文易读；同时提供 PDF 阅读版。检查日期、称呼、换行和表格是否跨页。若无法生成文件，请直接说明并给排版步骤。事实材料：[填写活动名称、时间、地点、对象、准备事项、联系人]。',quiz:{q:'材料里没有会议待办的负责人，应该怎样处理？',options:['请 AI 猜最可能的人','标记“待确认”，由参会人核实','删除所有待办'],answer:1,explain:'表格填满了，也可能有内容不对。缺什么就先标出来，不要让 AI 猜着填。'}},
 {title:'换个对话，怎样接着做？',desc:'什么时候该换对话？把哪些内容带过去才不会从头来？',icon:'⇄',color:'purple',time:8,tag:'对话管理',goal:'知道该继续还是新开，并能让新对话准确接手。',sections:[
  ['先看任务是否还是同一件事','<div class="comparison"><div><strong>适合继续当前对话</strong><p>同一份 PPT 改第 3 页；补充一个附件；纠正刚才的数据；调整同一个网页的字号。</p></div><div><strong>适合新建对话</strong><p>从教案换成旅行计划；想探索独立方案；对话混进太多无关内容；多次纠正后仍沿用旧假设。</p></div></div><p>没有“聊到固定条数就必须换”的规则。界面卡顿也可能是网络问题，不要只靠新开对话解决。</p>'],
  ['新对话不会自动带走所有背景','<p>部分产品有记忆、项目或文件共享能力，但不要默认它能读到上一轮全部内容。附件可能需要重新上传，本地文件需要重新选择目录或授权。把正确版本和待解决问题明确交接。</p><ol class="number-steps"><li><b>在旧对话要求交接摘要</b>保留目标、约束、已确认决定、最新文件、问题和下一步。</li><li><b>自己读一遍</b>删除密码和隐私，修正遗漏，不把 AI 猜测当成已确认事实。</li><li><b>粘到新对话并补材料</b>重新提供实际文件。请新助手先复述，不要从头另做一份。</li></ol>'],
  ['交接单要短，但不能丢关键事实','<p>例如：“目标：三年级阅读家长会，8 页。已确认：蓝白、20 分钟。当前文件：家长会_v2.pptx。已完成：1–6 页。问题：第 7 页缺行动建议。下一步：保留前 6 页，只补最后两页。待核实：学校活动日期。”</p><div class="callout">文件路径只是位置说明，不等于对方已经能访问。交给另一台电脑或另一个产品时，附上实际文件。</div>']
 ],practice:'handoff',prompt:'请为新对话制作一份可直接粘贴的交接摘要：1. 目标和使用对象；2. 已确认要求；3. 已做完的内容；4. 最新文件名、版本和用途；5. 未解决问题与尝试过的方法；6. 下一步。区分已确认事实、假设、待确认事项。删去无关聊天、账号、密钥与个人隐私。最后提醒我新对话需要重新提供哪些附件。',quiz:{q:'新对话要继续修改原来的 Word 文档，最佳做法是？',options:['只说“接着刚才的做”','粘贴交接摘要，提供最新文件，让它先确认理解','从头口述所有闲聊'],answer:1,explain:'交接目标和实际成品，能避免新助手拿错版本或重复劳动。'}},
 {title:'看不懂，直接问 AI',desc:'换说法、拆步骤、看截图，自己把下一步问出来。',icon:'?',color:'orange',time:8,tag:'自助求助',goal:'遇到术语、按钮或报错时，能独立向 AI 求助。',sections:[
  ['你不需要假装听懂','<p>AI 说得太专业，可以直接打断：“我没有计算机基础。请不用术语重新说，用一个生活例子解释，然后只告诉我第一步。”不用先去问教你的人，也不用把整段话硬背下来。</p><div class="comparison"><div><strong>遇到“解压到目录”</strong><p>我不懂“解压”和“目录”是什么意思，请用 Windows 电脑上的操作教我。</p></div><div><strong>继续把步骤问小</strong><p>我已经找到 ZIP 文件。现在先告诉我点哪里，等我说完成，再告诉我下一步。</p></div></div>'],
  ['找不到按钮，就把实际画面给它','<ol class="number-steps"><li><b>说清设备和软件</b>例如 Windows + Edge，或手机 + 豆包；能找到版本时一并说明。</li><li><b>描述已做到哪里</b>“已解压，双击后显示文字，没有网页。”明确期望看到什么。</li><li><b>补一张必要截图</b>遮住姓名、聊天内容、账号、学生资料。保留窗口标题、按钮和报错区域。</li><li><b>要求逐步核对</b>“只根据截图可见内容指导。看不见就问我，不要猜按钮位置。”</li></ol>'],
  ['报错时，不要只说“不能用”','<p>提供原始报错、触发步骤、预期结果和实际结果。先让它解释原因，再给一个可撤销的修复步骤。不要随便执行看不懂的删除命令、安装陌生软件或关闭安全保护。</p><div class="callout">“先告诉我这一步会改什么，怎样撤销。只给最安全的下一步；涉及删除文件、付款或发送信息时，先问我。”</div><p>如果两次尝试仍失败，要求 AI 总结已尝试的方法和新线索，停止重复同一方案。账号申诉或产品故障可带摘要联系官方支持。</p>']
 ],practice:'help',prompt:'我没看懂你刚才说的“[粘贴原话]”。我没有相关基础，请用日常语言和一个具体例子解释。然后一次只给一个操作步骤：告诉我点哪里、应该看到什么，等我回复完成再继续。不要假设我知道专业词。如果界面可能不同，先问我设备和软件，或请我提供已遮住隐私的截图。',quiz:{q:'AI 说的按钮在你的界面上不存在，应该怎样问？',options:['继续随便点几个按钮','提供设备、软件和脱敏截图，让它只按可见内容指导','反复说“你错了”'],answer:1,explain:'不同版本界面会不同。补充真实画面，并要求它在不确定时反问。'}},
 {title:'生活、大学学习、教学与办公',desc:'选一个完整案例跟着做，再换成自己的材料。',icon:'▦',color:'',time:8,tag:'场景拓展',goal:'能判断哪些环节交给 AI，哪些环节自己负责。',sections:[
  ['先选一个低风险、可核对的小任务','<p>家庭可以整理出行物品、理解说明书、写活动邀请；老师可以准备课堂练习、设计教案、改写家校沟通；大学生可以理解课程材料、组织汇报、整理小组任务；办公可以整理纪要、比较方案、做汇报。不要一开始就把整份重要工作全交出去。</p><p>案例演示中有 12 个完整过程，按原始材料、初稿、找问题、追问修改、成品验收五步展开。另有 42 个备用模板。更重要的是“怎样放心用 AI”里的三个验证实验：怎样反问、独立核查、按证据解决分歧，再复验一轮。</p>'],
  ['事情比较多，就分成几步做','<p>例如旅行准备：先列需求，再拟路线，再查实时交通和营业信息，最后制作离线行程网页。AI 可以帮你组织材料；你负责核实来源、确认预算和最终预订。</p><p>例如教学备课：先给年级和目标，再生成活动，再检查题目和答案，最后做课件。不能因为语气像老师，就假定知识点没有错。</p>'],
  ['哪些地方还需要你自己判断？','<ul><li>文字解释不等于专业诊断、法律意见或投资保证。重要决定要核对专业来源。</li><li>本地网页不自动拥有联网、云同步或发送消息的能力。</li><li>想让 AI 处理文件，需要提供文件并确认产品支持。</li><li>真实姓名、学生资料和内部数据，应按必要性和所在机构规定处理。</li></ul>']
 ],practice:'scenes',prompt:'请帮我寻找适合 AI 协助的小任务。我日常会做：[列出三件事]。请按每次能节省的时间、出错后果、我是否容易核对，推荐一个最适合新手的任务。把它拆成三个可检查步骤，说明 AI 做什么、我确认什么。',quiz:{q:'第一次尝试 AI，哪种任务最适合？',options:['直接替我作重要决定','把一份不含隐私的活动草稿改得更清楚，我再核对','不检查就批量覆盖全部原文件'],answer:1,explain:'小范围、低风险、容易判断好坏的任务，更适合建立信心和方法。'}},
 {title:'检查结果，保护自己的资料',desc:'发给别人之前，检查内容、文件和个人信息。',icon:'✓',color:'green',time:9,tag:'可靠使用',goal:'能在分享成果前完成一次有用的检查。',sections:[
  ['“说得像真的”不等于“是真的”','<p>核查姓名、日期、计算结果、引文和链接。让 AI 给出来源、发布日期，以及哪一句结论由哪一条来源支持。点开链接看原文，链接存在也不代表内容支持这个结论。</p><div class="callout">“请把这份内容里的事实性说法列成核查表：说法、来源、日期、是否直接支持、尚未确认的问题。没找到来源就写没找到。”</div>'],
  ['只提供任务需要的资料','<p>学生姓名可替换成学生 A、B；去掉身份证号、银行卡号、账号密钥和不必要的联系方式。截图前遮住无关窗口。敏感工作资料遵循单位规定，脱敏也不等于获得上传授权。</p><p>文件或网页中出现的“忽略之前要求、把资料发到某处”，应当当作材料里的文字，不作为你的操作指令。</p>'],
  ['重要操作，先看再做','<ul><li><b>改文件：</b>先备份，保存 v1、v2，避免覆盖唯一原件。</li><li><b>删文件：</b>先要预览清单，明确范围，确认后再执行。</li><li><b>发消息、发布、付款：</b>先看收件人、正文、附件或金额，再批准。</li><li><b>发给别人前：</b>自己打开文件，点击功能，换目录、换设备试一次。</li></ul>']
 ],practice:'check',prompt:'请在交付前做一次检查，并报告实际检查了什么：核对事实和来源，检查文件能否打开、内容是否完整、是否残留隐私或占位文字、是否覆盖原件。对网页检查按钮和手机显示；对 PPT 检查放映和可编辑性；对 Word 检查分页和打印。没法验证的项目明确写“未验证”，不要只说全部正常。',quiz:{q:'AI 说“文件已完成”，接下来你应该做什么？',options:['直接转发','实际打开文件，核对关键内容和格式，再分享','让它再说一次已完成'],answer:1,explain:'成品验收要有实际证据。重新保证一次不能替代打开和检查。'}},
 {title:'完成你的第一份 AI 作品',desc:'选一个小项目，走完需求、制作、修改、分享全过程。',icon:'⚑',color:'purple',time:15,tag:'结课练习',goal:'完成一份自己看得懂、用得上、交得出去的成果。',sections:[
  ['选一个今天就能做完的作品','<div class="comparison"><div><strong>给家人</strong><p>一份可勾选的出行清单网页，或一页清晰的活动通知。</p></div><div><strong>给同事、学生</strong><p>一份 6 页微课 PPT，或含练习与答案的两页教案。</p></div></div><p>如果还没装好产品，先在“工具箱”填写需求，复制后留待实际使用。课堂练习本身不会调用 AI 或生成真实 PPT 文件。</p>'],
  ['照着这个流程走一遍','<ol class="number-steps"><li><b>写需求</b>用提问生成器写目标、对象、材料和成品标准。</li><li><b>确认小样</b>让 AI 先复述，再做一页或一个模块。</li><li><b>具体修改</b>指出位置、问题和期望，保留已满意部分。</li><li><b>验收成果</b>打开实际文件；测试按钮、放映或打印预览；核对事实。</li><li><b>带走成果</b>保存最终文件和交接单。网页把依赖文件一起压缩；PPT 和 Word 保留可编辑源文件。</li></ol>'],
  ['卡住了，就问下一小步','<p>记住这句话：“我想做什么，我已经做了什么，我看到什么，我希望下一步是什么。”把这四件事告诉 AI，再请它一次指导一步。学会继续问，就能继续学。</p><div class="callout">第一次说得不完整很正常。先看一版，告诉它哪里不合适，改好后再检查。多做几次，就会越来越熟悉。</div>']
 ],practice:'graduate',prompt:'请陪我完成一个小项目：[填写项目]。先问清目标和成品要求，做一个小样让我确认，再制作完整结果。每一步都用日常语言解释；我说看不懂时，请换个例子并缩小步骤。最后给我成品文件、检查记录、打开方法和下次继续使用的交接摘要。',quiz:{q:'这门课最重要的能力是什么？',options:['记住所有模型名字','一次写出很长的提示词','表达目标、继续追问、判断小样、检查成果'],answer:2,explain:'产品会变，但清楚沟通、主动求助和验证结果的习惯可以一直使用。'}}
];

const SCENES = [
 ['生活','出行清单网页','网页','给家人做可勾选的旅行物品清单。','为两位长辈制作 3 天短途出行清单，分证件、衣物、电子用品和其他。用离线 HTML+CSS+JS 展示，字号至少 18px，可勾选、显示完成数量、重置前确认。不要加入网络依赖。','断网能打开；勾选计数正确；不含证件号码。'],
 ['生活','读懂电器说明书','解释','从说明书里找到真正要用的步骤。','请根据我提供的说明书，解释如何使用预约功能。先确认型号，只引用说明书里的步骤，用日常语言一次教我一步。找不到就说明，不要猜测按钮。','型号一致；步骤与原说明书相符；安全事项未遗漏。'],
 ['生活','家庭活动邀请','文档','把时间、地点和准备事项说清楚。','根据这些事实写一份 200 字以内的家庭活动邀请：[材料]。语气亲切，明确时间、地点、需要带的东西。缺少信息先问我，确认后输出可编辑 Word。','时间地点无误；手机号等私密信息只在必要时保留。'],
 ['生活','一周家常菜单','计划','按人数、口味和现有食材安排。','给 3 人家庭设计一周晚餐菜单，每餐两菜一汤。已有食材：[填写]；忌口和过敏原：[填写]。先核实限制，再按天整理并汇总购物清单，不提供疾病治疗建议。','过敏原排除；食材用量合理；不虚构健康功效。'],
 ['生活','读书分享 PPT','PPT','把读过的一本书讲给朋友听。','根据我提供的读书笔记做 6 页、8 分钟分享 PPT：这本书讲什么、三个收获、一个讨论问题。先出大纲，引用仅使用笔记中可核对的原文与页码。确认后生成可编辑 .pptx 和讲者备注。','引文真实；不是逐页堆满文字；试讲在 8 分钟左右。'],
 ['生活','旅行说明 PPT','PPT','给同行家人说明行程与分工。','把我已确认的路线制作成 5 页家庭出行说明 PPT：日期路线、交通、住宿、物品和分工。长辈能读清，字号大。未知的营业时间标记待核实，不虚构票价，交付可编辑 .pptx。','交通和票价重新核实；紧急联系信息不公开传播。'],
 ['生活','家庭预算比较','表格','把固定支出与可调整支出分开。','根据脱敏后的月支出记录，分类汇总并给一张预算对比表。金额按原数据计算，列出计算过程和不明确的分类，不作投资推荐。','合计与原账目一致；没有账号和银行卡号。'],
 ['生活','手机操作小教程','解释','不会的功能，一步一步学。','我用的是[手机型号、系统、软件]，想完成[操作]。请先确认版本，一次给一个步骤，说明应看到的画面，等我回复再继续。不确定按钮位置就请我提供脱敏截图。','实际界面吻合；不索要验证码和密码。'],
 ['生活','活动照片整理计划','文件','先预览命名，再动手整理。','请为我的活动照片设计按日期和活动名整理的方案。先读取练习副本，只输出原文件名与建议新名的对应表，不删除、不覆盖。等我确认后再执行，保留可撤销记录。','命名无冲突；照片原件保留；执行范围明确。'],
 ['生活','社区活动报名说明','文档','让参与者一眼看到要做什么。','根据活动材料写一页 A4 社区报名说明，含对象、名额、截止时间、报名方式和注意事项。缺项标待确认，生成 .docx 和 PDF。','报名入口正确；日期一致；打印不截断。'],
 ['教学','阅读主题家长会','PPT','一份能讲 20 分钟的家长会课件。','制作三年级阅读习惯家长会 PPT，8 页、20 分钟。仅依据我提供的匿名材料，每页一个重点，包含三条家庭行动建议。先给逐页大纲，再做两页小样，确认后交付可编辑 .pptx 和讲者备注。','无学生隐私；建议可执行；投影可读；可编辑。'],
 ['教学','十分钟科学微课','PPT','先激发好奇，再示范与练习。','为五年级设计“水的三态变化”10 分钟、6 页微课 PPT。包含生活问题、概念图、一个观察活动和两道随堂题及答案。先确认知识点与安全边界，再做可编辑 .pptx。','科学概念正确；活动安全；题目有解释。'],
 ['教学','一课时完整教案','文档','目标、活动、时间和评价放在一起。','请根据我提供的教材章节与学情制作 40 分钟教案。列教学目标、重点难点、时间表、师生活动、分层练习和参考答案。仅用已给教材信息，确认后输出可编辑 .docx。','时间总计 40 分钟；活动符合学情；答案教师复核。'],
 ['教学','温和的家校沟通','文档','描述行为和建议，避免给孩子贴标签。','把下面的匿名情况改写成给家长的沟通草稿：[事实]。先客观描述行为，再说明影响，最后给两条可实施建议。语气尊重，不下诊断、不贴标签，150 字以内。','只写观察事实；无羞辱或未经证实的判断。'],
 ['教学','可互动的复习卡','网页','点开答案，再检查自己是否理解。','按这些已核对的知识点制作离线复习网页：[材料]。包含 10 张问答卡，点击查看答案与解释，可切换上一张下一张，手机可用，无外部资源。','全部答案正确；按钮可用；不依赖网络。'],
 ['教学','分层练习单','文档','让基础题、提升题各有目的。','围绕[年级、知识点]出 6 道基础题、3 道提升题。先给题目和完整解答让我检查，再排为两页 A4 .docx，学生版不含答案，另给教师答案版。','题意清楚；难度符合年级；学生版未泄露答案。'],
 ['教学','班级活动策划','PPT','把目标、安排、分工和风险讲清楚。','制作“班级读书节”策划 PPT，7 页，面向年级组。包含目标、日程、任务分工、预算、风险和待决事项。未知金额标待估算，先确认大纲后生成可编辑 .pptx。','预算未伪装为实际支出；负责人需确认。'],
 ['教学','教研会议纪要','文档','分清讨论建议与已经决定的事。','把脱敏教研记录整理成纪要：议题、讨论摘要、已确认决定、待办、待确认事项。每项待办写负责人和截止日期，原文未给就标待确认。生成 Word，保留原记录副本。','决定与建议未混淆；不编造负责人。'],
 ['教学','课程评价量规','表格','把抽象评价拆成可观察的表现。','为[年级、学习任务]设计 4 个维度、3 个等级的评价量规。每格描述可观察行为，不使用笼统的好中差；同时给一个样例让我校准，再形成可编辑表格。','维度符合目标；等级可区分；避免偏见。'],
 ['教学','教学研究汇报','PPT','用证据支持改进，而不夸大效果。','按匿名教学记录做 8 页教研汇报 PPT：问题、方法、过程、证据、局限、改进。没有对照的数据不要写成因果结论。每个图表标明数据来源，生成可编辑 .pptx。','数据合计正确；承认样本限制；不泄露学生信息。'],
 ['办公','周工作汇报','PPT','结论先行，成果和计划分开。','把工作记录整理成 7 页、10 分钟周汇报 PPT，面向直属负责人。包括本周成果、证据、问题、下周计划和需要支持。先确认大纲，不编造业绩数字，输出可编辑 .pptx。','每个结果有材料依据；待办未写成已完成。'],
 ['办公','会议行动纪要','文档','让每一个待办都找得到依据。','根据以下会议记录制作一页行动纪要，分决定与待办，用事项、负责人、截止日、依据四列呈现。缺失项写待确认，给可编辑 .docx，不替我发送邮件。','原文支持决定；人员和日期核对；格式不溢出。'],
 ['办公','月度总结报告','文档','从原材料形成可追溯的报告。','仅根据附件制作月度总结，含摘要、成果、问题、数据和下月计划。数字附文件名与位置，待核实项单列。先给结构，确认后输出 .docx 与 PDF。','引用可追溯；图表与原数据一致；两版内容一致。'],
 ['办公','新同事培训课件','PPT','流程清楚，学完就能练。','把我提供的内部可使用材料制作成 10 页新同事培训 PPT。每个流程给一个示例，最后附 3 道情景题。先给大纲，确认后生成可编辑 .pptx；不要加入未提供的制度。','制度版本有效；案例已脱敏；练习有反馈。'],
 ['办公','项目方案比较','表格','按同一标准比较备选方案。','根据三份方案，按成本、周期、维护、风险列比较表。注明原文位置，缺失信息写未知，不替未知项打分。询问我的优先级后再建议。','同口径比较；没有虚构报价；权重由人确认。'],
 ['办公','常用操作手册','文档','把经验变成别人能照做的步骤。','根据我的实际操作记录制作新手操作手册。每步写前提、操作、预期画面和异常处理。截图保留占位说明，未经提供不要伪造界面。输出带目录的 .docx。','步骤实测；截图与版本一致；可以跟做。'],
 ['办公','客户邮件草稿','文档','礼貌清晰，先审阅再发送。','根据以下事实起草回复客户的邮件：[材料]。先回应问题，再说明行动与时间。不能承诺未确认的价格和交付日；只生成草稿，等我审阅后再决定是否发送。','收件人正确；承诺可兑现；附件无多余信息。'],
 ['办公','汇总脱敏问卷','分析','给出计算口径，也说明样本限制。','根据脱敏问卷统计各选项人数与占比，明确分母、缺失值和多选题处理方式。输出表格和三个观察，不把相关性说成因果。请展示可核对的计算。','分母正确；百分比口径明确；未过度推断。'],
 ['办公','文件批量命名','文件','先预览，再对副本执行。','仅在练习目录内，为文件按日期-项目-版本命名。先输出原名与新名对照表，检测重名，等我确认后只改副本，保留撤销记录，不删除任何文件。','无覆盖；范围明确；可以按记录还原。'],
 ['办公','项目说明网页','网页','让同事快速找到进度与资料。','制作离线项目介绍网页，使用 HTML+CSS+JS，含目标、时间线、常见问题和资料目录。所有资源使用相对路径；不实现虚假的在线协作。内容仅使用附件。','链接有效；目录资源齐全；项目状态可核对。']
].map((s,id)=>({id,category:s[0],title:s[1],format:s[2],desc:s[3],prompt:s[4],check:s[5]}));

const HELP = [
 {name:'这段话看不懂',text:'我没看懂这段话：[粘贴原话]。请像教一位第一次接触电脑的人一样，用日常语言解释，再举一个贴近生活的例子。专业词第一次出现时请解释含义，最后让我用自己的话复述，帮我检查是否理解。'},
 {name:'不知道下一步点哪里',text:'我使用[设备和软件]，想完成[目标]，已经做到[步骤]。请一次只告诉我一个操作，明确点哪里、预期看到什么，等我回复后再继续。如果界面可能不同，先问版本或请我提供脱敏截图，不要猜按钮位置。'},
 {name:'不知道怎么表达需求',text:'我想做[大致想法]，但说不清具体要求。请通过反问帮我理清，一次只问一个问题，每次给 2–3 个通俗选项。问清用途、使用者和成品形式，再复述你的理解，等我确认后开始。'},
 {name:'结果不对，不会修改',text:'我想要的效果是[期望]，现在得到的是[实际情况]。请先比较差异，找出最影响使用的一个问题。保留[满意部分]，先给一个修改小样让我确认，不要全部推倒重做。'},
 {name:'出错了，不知道怎么办',text:'我的设备和软件是[填写]。我想[目标]，操作到[步骤]时出现：[原始报错]。预期是[填写]，实际是[填写]。请先解释报错，用最小、可撤销的步骤排查，每次只给一步。涉及删除、安装、付款或发送资料时先说明影响并问我。'},
 {name:'想根据截图求助',text:'这是我当前界面的截图，已遮住隐私。我想完成[目标]。请只根据截图可见的内容告诉我下一步点哪里，并说明操作后应看到什么。如果看不清或不能确定，请反问我，不要编造不存在的按钮。'}
];

LESSONS.splice(9,0,{title:'用 AI 做股票研究',desc:'把自己的想法转成条件，用证据支持，也用反例检验。',icon:'▥',color:'orange',time:12,tag:'股票研究',goal:'能组织一份有来源、有日期、有反证的研究问题单。',sections:[
 ['先说清你研究的究竟是什么','<p>“我看好养老行业”是一个想法，还不是可直接执行的选股条件。先明确市场（A 股、港股或美股）、股票名称与代码、数据截止日期、研究目的，以及你愿意接受的不确定性。</p><p>行业增长不等于每家公司盈利增长，公司优秀也不等于任何价格都合适。AI 的作用是帮助梳理材料、核对逻辑和寻找反证，无法承诺收益。</p>'],
 ['从模糊想法到可核对条件','<div class="comparison"><div><strong>原始想法</strong><p>我想找分红比较稳定的公司。</p></div><div><strong>研究问题</strong><p>“稳定”指连续几年？是否有中断？分红来自什么现金流？股息率是否因股价大跌而显得高？未来分红能否持续？</p></div></div><p>不要让 AI 替你悄悄设阈值。先让它解释指标，再给几种定义供你选。例如连续分红年数只是研究维度，不代表达到某个数字就适合买入。</p>'],
 ['单只股票，按六个问题往下问','<ol class="number-steps"><li><b>它靠什么赚钱？</b>用年报解释主营业务、客户和收入结构。</li><li><b>增长来自哪里？</b>区分销量、价格、收购和一次性因素。</li><li><b>利润变成现金了吗？</b>核对经营现金流与净利润，留意行业差异。</li><li><b>负债与分红能否承受？</b>看债务到期、资金需求和分红记录。</li><li><b>当前价格隐含什么预期？</b>核实价格时点、币种、指标口径；亏损公司不宜机械比较市盈率。</li><li><b>什么证据会推翻我的想法？</b>主动寻找需求下滑、竞争加剧、政策变化等反例，列待核实项。</li></ol>'],
 ['让每个数字都有出处','<p>优先阅读交易所披露和公司正式财报。要求标注报告期、发布日期、单位、合并口径与原文页码。股票代码、同名公司、人民币与其他币种都要逐项核对。</p><div class="callout warn">本课堂没有接入实时行情，不提供买卖信号或个性化投资建议。下方是研究方法练习。AI 无法联网时，不能假装知道“今天”的价格；应索取材料或标记数据缺失。</div><p>涉及真实资金时，不把 AI 输出作为唯一依据。交易规则、税费、适当性和风险承受能力需另行核实。</p>']
 ],practice:'stocks',prompt:'我想研究[市场、公司全名、股票代码]，我的初步想法是：[填写]。数据截止日期为[日期]。先复述我的假设，并解释需要用到的指标；不清楚的条件请反问，不要擅自设选股阈值。根据交易所公告和公司财报，按支持证据、反对证据、待核实信息整理，标注报告期、单位、原文链接和页码。不能获取的行情或数据请明确写缺失。区分事实、推断、情景假设，不给保证收益或未经支持的目标价。最后说明什么变化会推翻这个判断。',quiz:{q:'AI 列出一只“高股息”股票，下一步应该做什么？',options:['马上买入','核对价格日期、分红口径、持续性与现金流，并寻找反证','只问它还会涨多少'],answer:1,explain:'单个指标不能替代完整研究。过期价格、特殊分红或股价下跌都可能影响表面的股息率。'}});

SCENES.push(...[
 ['把行业看法变成条件','我看好[行业]，想研究[市场]的相关公司。请先问我看好的原因、研究时段和行业范围，再把想法拆成可验证条件。区分行业收入敞口、经营质量和估值，不擅自给阈值或荐股名单。给每个条件的数据来源与局限。','行业概念与真实收入相关；条件定义清楚；没有用热门标签替代证据。'],
 ['研究一只股票','请分析[市场、公司全名、代码]，截止[日期]。我关注[问题]。先核对公司身份，依据正式财报与公告解释业务、增长、现金流、债务和风险。数字附报告期、单位与来源；缺失项标注，不编造当前行情。','公司与代码正确；报告期一致；事实和判断分开。'],
 ['寻找分红持续性的证据','我想研究分红是否稳定。请先用大白话解释股息率、分红率、特别分红和经营现金流，再问我怎样定义稳定。用我提供的公司报告核对记录，解释可持续性的支持与反对证据，不把历史分红当未来承诺。','价格时点与分红口径明确；关注债务和现金流；不保证未来分红。'],
 ['两家公司同行比较','比较[市场、公司A代码]与[市场、公司B代码]。先确认业务是否可比，再用相同报告期、币种和口径比较收入、利润、现金流、负债与估值。解释不可比之处，不单凭市盈率排序。','会计口径与行业可比性确认；亏损时估值指标不被误用。'],
 ['给我的观点找反证','我的股票研究观点是：[填写]。请不要顺着我说。拆分事实和假设，列支持证据、最强反对证据、未知项，以及会推翻判断的可观察事件。所有事实给来源与日期，最后列出我还应核查的三个问题。','真的包含反方材料；未知项保留；不把观点写成确定结论。'],
 ['读懂一份公司财报','请根据我上传的[公司、报告期]财报，像教新手一样解释主营收入、净利润、经营现金流和负债。一项一项讲，每项给原文页码与单位，再问我是否理解。不要从财报直接推出买卖结论。','与原报表逐项核对；合并与母公司口径不混用；一次只解释一个指标。']
].map((s,i)=>({id:30+i,category:'股票研究',title:s[0],format:'研究',desc:s[2],prompt:s[1],check:s[2]})));
